// Generates src/tokens.css from the app's design tokens (app/lib/theme.ts) — the console never forks
// colours. Run: `npm run tokens`. src/__tests__/tokens.test.ts fails if the two drift.
import { writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { colors, speakerPalette } from '../../../app/lib/theme';

export function renderTokensCss(
  palette: Readonly<Record<string, string>>,
  speakers: readonly string[],
): string {
  const lines = [
    '/* GENERATED by scripts/gen-tokens.ts from app/lib/theme.ts. Do not edit; run `npm run tokens`. */',
    ':root {',
    ...Object.entries(palette).map(([name, hex]) => `  --${name}: ${hex};`),
    ...speakers.map((hex, i) => `  --speaker-${i}: ${hex};`),
    '}',
    '',
  ];
  return lines.join('\n');
}

const isMain = process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isMain) {
  const out = resolve(dirname(fileURLToPath(import.meta.url)), '../src/tokens.css');
  writeFileSync(out, renderTokensCss(colors, speakerPalette));
  console.log(`wrote ${out}`);
}
